grid=[[5]*14 for _ in range(12)]
for r in [2]:
 for c in range(4,10): grid[r][c]=0
for r,c in [(4,3),(4,9),(5,9),(6,3),(6,9),(7,9),(8,3),(8,9),(9,3),(9,9)]: grid[r][c]=0
for c in range(3,8): grid[11][c]=0
grid[11][9]=0
# Fill background gaps strictly between marker cells in vertical and horizontal runs, based on original grid
orig=[row[:] for row in grid]
for r in range(12):
 occ=[c for c,v in enumerate(orig[r]) if v==0]
 for a,b in zip(occ,occ[1:]):
  for c in range(a+1,b):
   if orig[r][c]==5: grid[r][c]=2
for c in range(14):
 occ=[r for r in range(12) if orig[r][c]==0]
 for a,b in zip(occ,occ[1:]):
  for r in range(a+1,b):
   if orig[r][c]==5: grid[r][c]=2
assert len(grid)==12 and all(len(x)==14 for x in grid)
import json
print(json.dumps({'action':'submit','grid':grid}))
